SELECT COUNT(*)
FROM email_verification
WHERE email = #{email}
AND purpose = #{purpose}
AND created_at > NOW() - make_interval(secs => #{cooldownSeconds})

SELECT COUNT(*)
FROM email_verification
WHERE email = #{email}
AND purpose = #{purpose}
AND verified_at IS NOT NULL
AND verified_at > NOW() - make_interval(mins => #{validMinutes})
